/bin/bash -lc "npm test && node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createSchedule, listSchedules, runDueSchedules, deleteSchedule } from './src/server.js';
const s = createSchedule({accountId:'acct-1', channel:'email', destination:'a@example.com', frequency:'daily', time:'09:05'});
assert.equal(listSchedules('acct-1').length, 1);
let got;
const result = await runDueSchedules({now:new Date('2026-08-13T09:05:00Z'), deliver: async (schedule, report) => { got={schedule,report}; }});
assert.equal(result.length, 1);
assert.equal(got.report.summary.totalEvents, 1);
assert.equal((await runDueSchedules({now:new Date('2026-08-13T09:05:30Z'), deliver: async()=>{}})).length, 0);
assert.equal(deleteSchedule(s.id, 'acct-1'), true);
console.log('schedule smoke test passed');
EOF"

