/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createApp } from './src/server.js';
const app = createApp(); await new Promise(resolve => app.listen(0, resolve));
const port = app.address().port;
let response = await fetch("'`http://127.0.0.1:${port}/`); assert.equal(response.status, 200); assert.match(await response.text(), /Scheduled reports/);
response = await fetch(`http://127.0.0.1:${port}/api/schedules`, {method:'"'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({accountId:'http',channel:'webhook',destination:'https://example.test/hook',frequency:'daily',time:'10:00'})});
assert.equal(response.status, 201); const created = await response.json(); assert.equal(created.accountId, 'http');
response = await fetch("'`http://127.0.0.1:${port}/api/schedules?accountId=http`); assert.equal((await response.json()).length, 1);
app.close(); console.log('"'HTTP smoke test passed');
EOF"

